const csvHeader='name,apaar,institution,course,category';
function download(filename:string,text:string,mime='text/csv'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:mime}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function csvCell(s:string){return '"'+(/^[=+@\-]/.test(s)?"'"+s:s).replaceAll('"','""')+'"'}
function parseCSV(text:string){const rows:string[][]=[];let row:string[]=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw new Error('CSV has an unclosed quoted field.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);const headers=rows.shift()?.map(x=>x.trim().toLowerCase().replace(/^\uFEFF/,''))||[];if(!['name','apaar','institution','course'].every(x=>headers.includes(x)))throw new Error('Required columns: name, apaar, institution, course. Download the template to get started.');if(rows.length>500)throw new Error('Maximum 500 rows per batch.');return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,(r[i]||'').trim()])))}
function time(s:string){return new Date(s).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}
