 const all=useMemo(()=>data?issues(data):[],[data]);const open=all.filter(x=>!data?.resolved[x.id]);const scoped=data?.students.filter(s=>(role==='College staff'?s.institution==='INST-001':true)&&(inst==='all'||s.institution===inst))||[];
