 async function readFile(f?:File){if(!f)return;setUploadError('');setUpload([]);setFileName(f.name);if(!f.name.toLowerCase().endsWith('.csv'))return setUploadError('Please upload a CSV file. In Excel, choose Save As → CSV UTF-8.');if(f.size>2*1024*1024)return setUploadError('Maximum file size is 2 MB.');try{const rows=parseCSV(await f.text());if(!rows.length)throw new Error('The file contains no student rows.');setUpload(rows)}catch(e){setUploadError(e instanceof Error?e.message:'Unable to read CSV.')}}
