 {finding&&<Modal title="Record a review" subtitle={finding.title} close={()=>setFinding(null)}><p className="modal-copy">{finding.detail}</p><div className="notice"><Info size={16}/> A review acknowledges this finding. It does not change student data or establish official compliance.</div><label className="form-label">Review explanation<textarea rows={5} placeholder="Explain the evidence reviewed and the reason for your decision…" value={note} onChange={e=>setNote(e.target.value)}/></label><small className="muted">At least 10 characters. Saved with a timestamp.</small>{error&&<div className="inline-error">{error}</div>}<div className="modal-actions"><button className="btn" onClick={()=>setFinding(null)}>Cancel</button><button className="btn primary" disabled={busy||note.trim().length<10} onClick={async()=>{if(await save({action:'resolve',id:finding.id,note}))setFinding(null)}}>{busy?'Saving…':'Save review'}<Check size={15}/></button></div></Modal>}
 {manual&&<Modal title="Add a student" subtitle="Create a synthetic admission record" close={()=>setManual(false)}><form onSubmit={async e=>{e.preventDefault();if(await save({action:'import',rows:[manualForm]})){setManual(false);setManualForm({...manualForm,name:'',apaar:''})}}}><label className="form-label">Student name<input required value={manualForm.name} onChange={e=>setManualForm({...manualForm,name:e.target.value})}/></label><label className="form-label">APAAR ID<input required pattern="[0-9]{12}" maxLength={12} value={manualForm.apaar} onChange={e=>setManualForm({...manualForm,apaar:e.target.value})}/></label><label className="form-label">Institution<select value={manualForm.institution} disabled={role==='College staff'} onChange={e=>setManualForm({...manualForm,institution:e.target.value})}>{institutions.map(i=><option value={i.id} key={i.id}>{i.name}</option>)}</select></label><label className="form-label">Programme<select value={manualForm.course} onChange={e=>setManualForm({...manualForm,course:e.target.value})}>{programmes.map(c=><option key={c}>{c}</option>)}</select></label><label className="form-label">Category<select value={manualForm.category} onChange={e=>setManualForm({...manualForm,category:e.target.value})}>{categories.map(c=><option key={c}>{c}</option>)}</select></label>{error&&<div className="inline-error">{error}</div>}<div className="modal-actions"><button type="button" className="btn" onClick={()=>setManual(false)}>Cancel</button><button disabled={busy} className="btn primary">{busy?'Saving…':'Add student'}<Plus size={15}/></button></div></form></Modal>}
 {certificate&&<Modal title="Certificate identifier preview" subtitle="SYNTHETIC DISPLAY PROTOTYPE" close={()=>setCertificate(null)}><div className="certificate"><div className="certificate-mark"><GraduationCap size={28}/></div><span>DEMO DEGREE-AWARDING BODY</span><h2>Provisional Academic Certificate</h2><p>This is to certify that</p><h3>{certificate.name}</h3><p>has an active reported enrolment in</p><strong>{certificate.course}</strong><div className="certificate-ids"><div><span>STUDENT ID</span><b>{certificate.id}</b></div><div><span>APAAR ID</span><b>{certificate.apaar||'NOT AVAILABLE'}</b></div></div><small>Academic year {certificate.year} · Synthetic prototype record · Not a valid certificate</small></div><div className="modal-actions no-print"><button className="btn" onClick={()=>setCertificate(null)}>Close</button><button className="btn primary" onClick={()=>window.print()}><Printer size={15}/> Print preview</button></div></Modal>}
 {showGuide&&<Modal title="AICTE student data workspace" subtitle="SIH 26263 · Concept prototype" close={()=>setShowGuide(false)}><div className="guide-intro"><ShieldCheck size={32}/><p>This platform connects institution submissions, APAAR-linked records, automated validation and accountable regulatory review.</p></div><ol className="guide-list"><li>Explore 10,000 synthetic records across 12 institutions.</li><li>Submit a sample CSV and preview validation findings.</li><li>Review duplicates, missing identifiers and intake exceptions.</li><li>Correct a record or record an authorized review decision.</li><li>Try the consent-controlled stakeholder verification flow.</li></ol><div className="notice">This is an independent concept prototype, not an official AICTE portal. All institutions and student records are synthetic. Role switching demonstrates perspectives, not production permissions. No live APAAR service is connected.</div><div className="modal-actions"><button className="btn primary" onClick={()=>{setShowGuide(false);go('Upload records')}}>Try a submission <ArrowRight size={15}/></button></div></Modal>}
