function Badge({tone,children}:{tone:string;children:React.ReactNode}){return <span className={'badge '+tone}><span/>{children}</span>}
function Stat({label,value,icon:Icon,footer,trend,warning=false}:any){return <section className={'stat '+(warning?'warning':'')}><div className="stat-top"><span>{label}</span><Icon size={18}/></div><strong>{value}</strong><span className="stat-trend">{warning?<AlertTriangle size={12}/>:<span className="tiny-dot"/>}{trend}</span><p>{footer}</p></section>}
function Empty({title,text}:{title:string;text:string}){return <div className="empty"><CheckCircle2 size={28}/><h3>{title}</h3><p>{text}</p></div>}
function Modal({title,subtitle,close,children}:{title:string;subtitle:string;close:()=>void;children:React.ReactNode}){const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const prev=document.activeElement as HTMLElement;const old=document.body.style.overflow;document.body.style.overflow='hidden';ref.current?.focus();function key(e:KeyboardEvent){if(e.key==='Escape')close();if(e.key==='Tab'){const nodes=ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input,select,textarea,a[href]');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===ref.current)){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}document.addEventListener('keydown',key);return()=>{document.body.style.overflow=old;document.removeEventListener('keydown',key);prev?.focus()}},[]);return <div className="modal-backdrop" onClick={close}><div ref={ref} tabIndex={-1} className="modal" role="dialog" aria-modal="true" aria-label={title} onClick={e=>e.stopPropagation()}><div className="modal-header"><div><span className="eyebrow">{subtitle}</span><h2>{title}</h2></div><button className="icon-btn" aria-label="Close dialog" onClick={close}><X size={21}/></button></div>{children}</div></div>}
const chartTooltip={contentStyle:{border:'1px solid #d7e0e8',borderRadius:8,boxShadow:'0 10px 30px #18324b1a',fontSize:11},labelStyle:{fontWeight:700,color:'#183b59'}};
function AdmissionChart({students}:{students:Student[]}){const data=Array.from({length:14},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-13+i);return {date:d.toLocaleDateString('en-IN',{day:'numeric',month:'short'}),submissions:students.filter(s=>{const created=new Date(s.createdAt);created.setHours(0,0,0,0);return created.getTime()===d.getTime()}).length}});return <div className="rechart-wrap activity-chart" role="img" aria-label="Student record submissions over fourteen days"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data} margin={{top:10,right:10,left:-18,bottom:0}}><defs><linearGradient id="activityFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#2f80c1" stopOpacity={.35}/><stop offset="100%" stopColor="#2f80c1" stopOpacity={.02}/></linearGradient></defs><CartesianGrid stroke="#e7edf3" strokeDasharray="3 5" vertical={false}/><XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fontSize:9,fill:'#748595'}} interval={1}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:9,fill:'#748595'}}/><Tooltip {...chartTooltip}/><Area type="monotone" dataKey="submissions" stroke="#1766a6" strokeWidth={3} fill="url(#activityFill)" activeDot={{r:5,strokeWidth:3,stroke:'#fff'}}/></AreaChart></ResponsiveContainer></div>}

function ChartPanel({title,subtitle,children,wide=false}:{title:string;subtitle:string;children:React.ReactNode;wide?:boolean}){return <section className={'panel insight-chart '+(wide?'wide':'')}><div className="panel-heading"><div><h2>{title}</h2><p>{subtitle}</p></div><button className="chart-menu" aria-label={`More options for ${title}`}>•••</button></div><div className="chart-body">{children}</div></section>}
function MetricsDashboard({students,findings}:{students:Student[];findings:Issue[]}){const active=students.filter(s=>s.status==='Active'),colors=['#1766a6','#4a8f78','#e39b36','#8c6bb1','#d06d5b','#5e7184'];const institutionRows=institutions.filter(inst=>students.some(s=>s.institution===inst.id)).map(inst=>({name:inst.initials,enrolled:active.filter(s=>s.institution===inst.id&&s.category!=='Supernumerary').length,intake:programmes.reduce((n,p)=>n+capacity(inst.id,p),0)}));const programmeRows=programmes.map(name=>({name:name.replace('Electronics & Communication','Electronics').replace('Artificial Intelligence & Data Science','AI & Data Science').replace(' Engineering',''),students:active.filter(s=>s.course===name).length}));const categoryRows=categories.map(name=>({name:name==='Foreign National'?'Foreign National':name,value:active.filter(s=>s.category===name).length}));const statusRows=['Active','Transferred','Withdrawn'].map(name=>({name,value:students.filter(s=>s.status===name).length}));const findingNames:Record<string,string>={intake:'Intake exceeded','missing-id':'Missing APAAR','invalid-id':'Invalid APAAR','duplicate-record':'Duplicate record','cross-institution-enrolment':'Cross-institution','missing-name':'Missing name','inconsistent-name':'Name inconsistency','inconsistent-data':'Reference mismatch','inconsistent-year':'Year inconsistency'};const findingMap=new Map<string,number>();for(const finding of findings)findingMap.set(finding.kind,(findingMap.get(finding.kind)||0)+1);const findingRows=[...findingMap].map(([kind,value])=>({name:findingNames[kind]||kind,value})).sort((a,b)=>b.value-a.value);return <section className="metrics-section"><div className="metrics-title"><div><span className="eyebrow">EXECUTIVE ANALYTICS</span><h2>Every signal, one operational view.</h2><p>Interactive metrics recalculate with the selected institution and current workspace.</p></div><Badge tone="neutral">{students.length.toLocaleString('en-IN')} records in view</Badge></div><div className="insight-grid"><ChartPanel title="Institution capacity position" subtitle="Active enrolment compared with configured approved intake" wide><ResponsiveContainer width="100%" height="100%"><BarChart data={institutionRows} margin={{top:8,right:8,left:-18,bottom:0}}><CartesianGrid stroke="#e8edf2" strokeDasharray="3 5" vertical={false}/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize:9,fill:'#667b8d'}}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:9,fill:'#667b8d'}}/><Tooltip {...chartTooltip}/><Legend iconType="circle" wrapperStyle={{fontSize:10}}/><Bar dataKey="enrolled" name="Reported enrolment" fill="#1766a6" radius={[4,4,0,0]}/><Bar dataKey="intake" name="Approved intake" fill="#b9cddd" radius={[4,4,0,0]}/></BarChart></ResponsiveContainer></ChartPanel><ChartPanel title="Programme portfolio" subtitle="Active students by programme"><ResponsiveContainer width="100%" height="100%"><BarChart data={programmeRows} layout="vertical" margin={{top:0,right:16,left:8,bottom:0}}><CartesianGrid stroke="#edf1f4" horizontal={false}/><XAxis type="number" hide/><YAxis type="category" dataKey="name" axisLine={false} tickLine={false} width={82} tick={{fontSize:9,fill:'#526879'}}/><Tooltip {...chartTooltip}/><Bar dataKey="students" fill="#4a8f78" radius={[0,5,5,0]} barSize={16}/></BarChart></ResponsiveContainer></ChartPanel><ChartPanel title="Admission mix" subtitle="Category distribution for active enrolments"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={categoryRows} dataKey="value" nameKey="name" innerRadius={52} outerRadius={78} paddingAngle={2}>{categoryRows.map((_,i)=><Cell key={i} fill={colors[i%colors.length]}/>)}</Pie><Tooltip {...chartTooltip}/><Legend iconType="circle" wrapperStyle={{fontSize:9}}/></PieChart></ResponsiveContainer></ChartPanel><ChartPanel title="Record lifecycle" subtitle="Active, transferred and withdrawn"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={statusRows} dataKey="value" nameKey="name" cx="50%" cy="48%" innerRadius={48} outerRadius={75}>{statusRows.map((_,i)=><Cell key={i} fill={['#1766a6','#e39b36','#7b8792'][i]}/>)}</Pie><Tooltip {...chartTooltip}/><Legend iconType="circle" wrapperStyle={{fontSize:9}}/></PieChart></ResponsiveContainer></ChartPanel><ChartPanel title="Open validation signals" subtitle="Findings grouped by validation rule"><ResponsiveContainer width="100%" height="100%"><BarChart data={findingRows.length?findingRows:[{name:'No findings',value:0}]} layout="vertical" margin={{top:0,right:20,left:15,bottom:0}}><XAxis type="number" hide/><YAxis type="category" dataKey="name" axisLine={false} tickLine={false} width={100} tick={{fontSize:9,fill:'#526879'}}/><Tooltip {...chartTooltip}/><Bar dataKey="value" name="Open findings" fill="#d47b2a" radius={[0,5,5,0]} barSize={15}/></BarChart></ResponsiveContainer></ChartPanel></div></section>}

function PolicyTwin({students}:{students:Student[]}){
 const [changes,setChanges]=useState<Record<string,number>>(Object.fromEntries(institutions.map(i=>[i.id,0])));
 const [scenarioName,setScenarioName]=useState('Intake review scenario'),[saved,setSaved]=useState<any[]>([]),[saving,setSaving]=useState(false),[serverError,setServerError]=useState('');
 async function loadSaved(){try{const res=await fetch('/api/policy-twin');const body=await res.json() as any;if(!res.ok)throw new Error(body.error);setSaved(body.scenarios||[])}catch(e){setServerError(e instanceof Error?e.message:'Unable to load scenarios.')}}
 useEffect(()=>{loadSaved()},[]);
 const rows=institutions.map(inst=>{const baseline=programmes.reduce((n,p)=>n+capacity(inst.id,p),0);const proposed=Math.max(1,Math.round(baseline*(1+(changes[inst.id]||0)/100)));const enrolled=students.filter(s=>s.institution===inst.id&&s.status==='Active'&&s.category!=='Supernumerary').length;const delta=proposed-enrolled;return {inst,baseline,proposed,enrolled,delta}});
 const breaches=rows.filter(r=>r.delta<0),baselineSeats=rows.reduce((n,r)=>n+r.baseline,0),proposedSeats=rows.reduce((n,r)=>n+r.proposed,0),affected=Math.abs(proposedSeats-baselineSeats);
 function exportScenario(){download('explainable-policy-twin-scenario.json',JSON.stringify({prototype:true,academicYear:'2026–27',createdAt:new Date().toISOString(),summary:{baselineSeats,proposedSeats,seatChange:proposedSeats-baselineSeats,projectedBreaches:breaches.length},institutions:rows.map(r=>({institutionId:r.inst.id,institution:r.inst.name,currentApprovedIntake:r.baseline,proposedIntake:r.proposed,reportedEnrolment:r.enrolled,projectedPosition:r.delta,explanation:r.delta<0?`${Math.abs(r.delta)} reported admissions would exceed the simulated intake.`:`${r.delta} seats remain under the simulated intake.`}))},null,2),'application/json')}
 async function saveScenario(){setSaving(true);setServerError('');try{const res=await fetch('/api/policy-twin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:scenarioName,adjustments:changes})});const body=await res.json() as any;if(!res.ok)throw new Error(body.error);await loadSaved()}catch(e){setServerError(e instanceof Error?e.message:'Unable to save scenario.')}finally{setSaving(false)}}
 async function deleteScenario(id:string){setServerError('');try{const res=await fetch('/api/policy-twin?id='+encodeURIComponent(id),{method:'DELETE'});const body=await res.json() as any;if(!res.ok)throw new Error(body.error);setSaved(saved.filter(s=>s.id!==id))}catch(e){setServerError(e instanceof Error?e.message:'Unable to delete scenario.')}}
 return <div className="twin-shell"><section className="twin-hero"><div><span className="twin-label"><FileCheck2 size={14}/> POLICY PLANNING MODULE</span><h2>Intake Impact Assessment</h2><p>Evaluate proposed changes in approved intake against reported student-level enrolment. Each result shows the applicable figures and calculation used for the assessment.</p></div><div className="twin-stamp"><SlidersHorizontal size={25}/><strong>SERVER CALCULATION</strong><span>Recorded in audit trail</span></div></section><div className="twin-metrics"><section><span>Existing approved intake</span><b>{baselineSeats}</b><small>As per configured records</small></section><section><span>Proposed intake</span><b>{proposedSeats}</b><small className={proposedSeats-baselineSeats<0?'risk':''}>{proposedSeats-baselineSeats>=0?'+':''}{proposedSeats-baselineSeats} seat change</small></section><section><span>Institutions requiring review</span><b className={breaches.length?'risk':''}>{breaches.length}</b><small>{breaches.length?'Further examination required':'No exception identified'}</small></section><section><span>Seats affected</span><b>{affected}</b><small>Under the current proposal</small></section></div><div className="twin-grid"><section className="panel twin-controls"><div className="panel-heading"><div><h2>Proposed intake adjustment</h2><p>Select the percentage change for each institution</p></div><button className="text-btn" onClick={()=>setChanges(Object.fromEntries(institutions.map(i=>[i.id,0])))}>Restore existing values</button></div>{rows.map(r=><label className="twin-slider" key={r.inst.id}><span><b>{r.inst.short}</b><small>{r.baseline} existing → {r.proposed} proposed seats</small></span><strong className={(changes[r.inst.id]||0)<0?'risk':''}>{(changes[r.inst.id]||0)>0?'+':''}{changes[r.inst.id]||0}%</strong><input type="range" min="-30" max="30" step="5" value={changes[r.inst.id]||0} onChange={e=>setChanges({...changes,[r.inst.id]:Number(e.target.value)})} aria-label={`${r.inst.short} intake adjustment`}/><span className="range-labels"><i>−30%</i><i>Existing</i><i>+30%</i></span></label>)}<div className="scenario-save"><input value={scenarioName} maxLength={80} onChange={e=>setScenarioName(e.target.value)} aria-label="Assessment name"/><button className="btn primary" disabled={saving||!scenarioName.trim()} onClick={saveScenario}>{saving?'Saving…':'Save assessment'}<Database size={14}/></button></div><button className="btn full" onClick={exportScenario}><Download size={15}/> Download assessment data</button></section><section className="panel twin-impact"><div className="panel-heading"><div><h2>Assessment result</h2><p>Calculated from current reported enrolment</p></div><Badge tone={breaches.length?'amber':'green'}>{breaches.length?'Review required':'Within limits'}</Badge></div>{rows.map(r=><div className={'impact-row '+(r.delta<0?'breach':'')} key={r.inst.id}><span className="impact-status">{r.delta<0?<AlertTriangle size={17}/>:<CheckCircle2 size={17}/>}</span><div><strong>{r.inst.short}</strong><p>{r.delta<0?<><b>{Math.abs(r.delta)} reported admissions</b> would exceed the proposed intake of {r.proposed}.</>:<><b>{r.delta} seats</b> remain after accounting for {r.enrolled} reported admissions.</>}</p></div><span className="impact-number">{r.enrolled} / {r.proposed}</span></div>)}<div className="twin-explanation"><ScanSearch size={17}/><p><strong>Basis of assessment:</strong> Each result is calculated from the configured approved intake, proposed percentage change and current reported enrolment. No undisclosed scoring model is used.</p></div></section></div>{serverError&&<div className="inline-error">{serverError}</div>}<section className="panel saved-scenarios"><div className="panel-heading"><div><h2>Saved assessments</h2><p>Server-calculated records available for comparison and audit</p></div><Badge tone="neutral">{saved.length} saved</Badge></div>{saved.length?saved.map(s=><div className="saved-scenario" key={s.id}><span><History size={17}/></span><div><strong>{s.name}</strong><small>{time(s.createdAt)} · {s.result.summary.projectedBreaches} institution(s) for review · {s.result.summary.seatChange>=0?'+':''}{s.result.summary.seatChange} seats</small></div><button className="btn" onClick={()=>setChanges(s.adjustments)}>Load</button><button className="icon-btn" aria-label={'Delete '+s.name} onClick={()=>deleteScenario(s.id)}><X size={16}/></button></div>):<Empty title="No saved assessments" text="Enter proposed adjustments and save the first assessment."/>}</section><div className="notice"><Info size={17}/> Demonstration module using synthetic records and configured intake values. Production use requires approved, versioned institution and programme data.</div></div>
}

function AcademicIntelligence({students,findings}:{students:Student[];findings:Issue[]}){
 const duplicate=findings.find(i=>i.kind==='duplicate'&&i.studentId);
 const primary=students.find(s=>s.id===duplicate?.studentId)||students[0];
 const related=primary?.apaar?students.filter(s=>s.apaar===primary.apaar&&s.id!==primary.id):[];
 const second=related[0]||students.find(s=>s.institution!==primary?.institution)||students[1];
 const [mode,setMode]=useState<'Timeline'|'Relationship graph'|'Conflict comparison'>('Timeline');
 const [selected,setSelected]=useState('conflict');
 if(!primary)return <section className="panel"><Empty title="No student records" text="Import synthetic student records to explore academic intelligence."/></section>;
 const firstInstitution=institutions.find(i=>i.id===primary.institution);
 const secondInstitution=institutions.find(i=>i.id===second?.institution);
 const events=[
  {id:'admission',year:'2023',title:'Admission recorded',detail:`${firstInstitution?.short} · ${primary.course}`,tone:'good',status:'Consistent',source:'Institution admission register'},
  {id:'result',year:'2024',title:'Semester result submitted',detail:`${firstInstitution?.short} · Academic record`,tone:'good',status:'Consistent',source:'Synthetic result ledger'},
  {id:'conflict',year:'2025',title:'Second enrolment reported',detail:`${secondInstitution?.short||'Another institution'} · ${second?.course||'Different programme'}`,tone:'risk',status:'Review needed',source:'Cross-institution enrolment record'},
  {id:'exam',year:'2026',title:'Examination registration',detail:'Date overlaps the reported academic sequence',tone:'warn',status:'Timeline conflict',source:'Synthetic examination register'},
 ];
 const selectedEvent=events.find(e=>e.id===selected)||events[2];
 return <div className="intel-shell">
  <div className="intel-toolbar panel"><div><span className="eyebrow">SYNCHRONIZED INVESTIGATION VIEW</span><h2>{primary.name||'Name unavailable'} <small>{primary.id} · Demo APAAR {primary.apaar||'not supplied'}</small></h2></div><div className="intel-tabs" role="tablist" aria-label="Academic intelligence visualization">{(['Timeline','Relationship graph','Conflict comparison'] as const).map(item=><button key={item} role="tab" aria-selected={mode===item} className={mode===item?'selected':''} onClick={()=>setMode(item)}>{item==='Timeline'?<CalendarClock size={15}/>:item==='Relationship graph'?<Network size={15}/>:<GitCompare size={15}/>} {item}</button>)}</div></div>
  <div className="intel-layout">
   <section className="panel intel-canvas">
    <div className="panel-heading"><div><h2>{mode==='Timeline'?'Personal academic timeline':mode==='Relationship graph'?'Cross-institution relationship graph':'Conflict comparison'}</h2><p>Illustrative analysis from synthetic records · not official APAAR verification</p></div><Badge tone="amber">2 signals to review</Badge></div>
    {mode==='Timeline'&&<div className="academic-timeline" role="list" aria-label="Synthetic academic events">{events.map(event=><button role="listitem" key={event.id} className={'timeline-event '+event.tone+(selected===event.id?' selected':'')} onClick={()=>setSelected(event.id)}><span className="timeline-dot"/><span className="timeline-year">{event.year}</span><span className="timeline-copy"><strong>{event.title}</strong><small>{event.detail}</small></span><span className={'timeline-status '+event.tone}>{event.status}</span></button>)}</div>}
    {mode==='Relationship graph'&&<div className="relationship-graph" aria-label="Relationship graph connecting a student, two institutions, a programme and source records"><span className="graph-line line-a"/><span className="graph-line line-b"/><span className="graph-line line-c"/><span className="graph-line line-d"/><button className="graph-node student-node" onClick={()=>setSelected('conflict')}><Users size={20}/><strong>{primary.name}</strong><small>Student record</small></button><button className="graph-node institution-node one" onClick={()=>setSelected('admission')}><Building2 size={18}/><strong>{firstInstitution?.short}</strong><small>Institution A</small></button><button className="graph-node institution-node two risk" onClick={()=>setSelected('conflict')}><Building2 size={18}/><strong>{secondInstitution?.short||'Institution B'}</strong><small>Overlapping record</small></button><button className="graph-node programme-node" onClick={()=>setSelected('result')}><BookOpen size={18}/><strong>{primary.course}</strong><small>Programme</small></button><button className="graph-node evidence-node" onClick={()=>setSelected('exam')}><Database size={18}/><strong>4 source records</strong><small>Evidence</small></button></div>}
    {mode==='Conflict comparison'&&<div className="conflict-compare"><div className="compare-axis"><span>2023</span><span>2024</span><span>2025</span><span>2026</span></div><div className="compare-row"><div><strong>{firstInstitution?.short}</strong><small>{primary.course}</small></div><button className="compare-bar valid" onClick={()=>setSelected('admission')}>Admission → active enrolment</button></div><div className="compare-row"><div><strong>{secondInstitution?.short||'Institution B'}</strong><small>{second?.course||'Second programme'}</small></div><button className="compare-bar conflict" onClick={()=>setSelected('conflict')}>Overlapping enrolment</button></div><div className="compare-overlap"><AlertTriangle size={15}/><span>Possible overlap</span><small>Verify transfer, concurrent study, correction or data-entry error.</small></div></div>}
    <div className="intel-legend"><span><i className="good"/>Consistent</span><span><i className="warn"/>Needs context</span><span><i className="risk"/>Potential conflict</span></div>
   </section>
   <aside className="panel evidence-panel"><div className="evidence-head"><span className={'evidence-icon '+selectedEvent.tone}><ScanSearch size={20}/></span><div><span className="eyebrow">EXPLAINABLE FINDING</span><h2>{selectedEvent.title}</h2></div></div><div className="evidence-section"><h3>What conflicts</h3><p>{selectedEvent.id==='conflict'?'Two institutions report enrolments linked to the same synthetic identifier during an overlapping period.':'This event is shown in context with the student’s other reported academic records.'}</p></div><div className="evidence-section"><h3>Why it matters</h3><p>Overlapping records can indicate a valid transfer or concurrent study, but they require evidence before a decision.</p></div><div className="evidence-section"><h3>Evidence</h3><div className="source-card"><Database size={16}/><div><strong>{selectedEvent.source}</strong><small>Recorded in synthetic workspace · {selectedEvent.year}</small></div></div><div className="source-card"><Building2 size={16}/><div><strong>{firstInstitution?.name}</strong><small>Institution-supplied demo record</small></div></div></div><div className="evidence-section"><h3>Alternative explanations</h3><div className="reason-chips"><span>Transfer</span><span>Concurrent study</span><span>Correction</span><span>Data-entry error</span></div></div><div className="next-action"><strong>Recommended next action</strong><p>Inspect source documents and request clarification before recording a review decision.</p></div></aside>
  </div>
  <div className="notice"><Info size={17}/> This visualization explains potential inconsistencies; it does not determine misconduct or confirm official APAAR authenticity.</div>
 </div>
}
